//! FlatBuffers, with code generated by `flatc` 25.12.19 from `schema/packets.fbs` (`packets_generated.rs`).
//! Decoding runs the FlatBuffers verifier (`root_as_packet`) before any field is read.

use flatbuffers::FlatBufferBuilder;

use crate::formats::Format;
use crate::model::*;
use crate::packets_generated::wire as fb;

#[derive(Default)]
pub struct Flat {
    builder: FlatBufferBuilder<'static>,
}

fn fb_entity(e: &Entity) -> fb::Entity {
    fb::Entity::new(
        e.id, e.pos[0], e.pos[1], e.pos[2], e.vel[0], e.vel[1], e.vel[2], e.rot,
    )
}

fn entity(e: &fb::Entity) -> Entity {
    Entity {
        id: e.id(),
        pos: [e.px(), e.py(), e.pz()],
        vel: [e.vx(), e.vy(), e.vz()],
        rot: e.rot(),
    }
}

fn entity_sum(e: &fb::Entity) -> u64 {
    u64::from(e.id())
        .wrapping_add(e.px() as u64)
        .wrapping_add(e.py() as u64)
        .wrapping_add(e.pz() as u64)
        .wrapping_add(e.vx() as u64)
        .wrapping_add(e.vy() as u64)
        .wrapping_add(e.vz() as u64)
        .wrapping_add(u64::from(e.rot()))
}

/// Visits an argument as the owned model type.
fn arg(a: &fb::ArgBox<'_>) -> Option<Arg> {
    Some(match a.arg_type() {
        fb::Arg::BoolArg => Arg::Bool(a.arg_as_bool_arg()?.value()),
        fb::Arg::IntArg => Arg::Int(a.arg_as_int_arg()?.value()),
        fb::Arg::FloatArg => Arg::Float(a.arg_as_float_arg()?.value()),
        fb::Arg::StrArg => Arg::Str(a.arg_as_str_arg()?.value()?.to_owned()),
        _ => return None,
    })
}

impl Format for Flat {
    fn name(&self) -> &'static str {
        "flatbuffers"
    }

    fn encode(&mut self, p: &Packet) -> &[u8] {
        let b = &mut self.builder;
        b.reset();
        let (kind, message) = match p {
            Packet::Snapshot(s) => {
                let list: Vec<fb::Entity> = s.entities.iter().map(fb_entity).collect();
                let entities = b.create_vector(&list);
                let m = fb::Snapshot::create(
                    b,
                    &fb::SnapshotArgs {
                        seq: s.seq,
                        tick: s.tick,
                        entities: Some(entities),
                    },
                );
                (fb::Message::Snapshot, m.as_union_value())
            }
            Packet::ClientState(c) => {
                let me = fb_entity(&c.me);
                let m = fb::ClientState::create(
                    b,
                    &fb::ClientStateArgs {
                        seq: c.seq,
                        tick: c.tick,
                        me: Some(&me),
                        buttons: c.buttons,
                        aim_x: c.aim[0],
                        aim_y: c.aim[1],
                    },
                );
                (fb::Message::ClientState, m.as_union_value())
            }
            Packet::Chat(c) => {
                let text = b.create_string(&c.text);
                let m = fb::Chat::create(
                    b,
                    &fb::ChatArgs {
                        seq: c.seq,
                        tick: c.tick,
                        from: c.from,
                        channel: c.channel,
                        text: Some(text),
                    },
                );
                (fb::Message::Chat, m.as_union_value())
            }
            Packet::ScriptEvent(e) => {
                let name = b.create_string(&e.name);
                let mut boxes = Vec::with_capacity(e.args.len());
                for a in &e.args {
                    let (t, v) = match a {
                        Arg::Bool(v) => (
                            fb::Arg::BoolArg,
                            fb::BoolArg::create(b, &fb::BoolArgArgs { value: *v }).as_union_value(),
                        ),
                        Arg::Int(v) => (
                            fb::Arg::IntArg,
                            fb::IntArg::create(b, &fb::IntArgArgs { value: *v }).as_union_value(),
                        ),
                        Arg::Float(v) => (
                            fb::Arg::FloatArg,
                            fb::FloatArg::create(b, &fb::FloatArgArgs { value: *v }).as_union_value(),
                        ),
                        Arg::Str(s) => {
                            let s = b.create_string(s);
                            (
                                fb::Arg::StrArg,
                                fb::StrArg::create(b, &fb::StrArgArgs { value: Some(s) }).as_union_value(),
                            )
                        }
                    };
                    boxes.push(fb::ArgBox::create(
                        b,
                        &fb::ArgBoxArgs {
                            arg_type: t,
                            arg: Some(v),
                        },
                    ));
                }
                let args = b.create_vector(&boxes);
                let m = fb::ScriptEvent::create(
                    b,
                    &fb::ScriptEventArgs {
                        seq: e.seq,
                        tick: e.tick,
                        name: Some(name),
                        args: Some(args),
                    },
                );
                (fb::Message::ScriptEvent, m.as_union_value())
            }
        };
        let root = fb::Packet::create(
            b,
            &fb::PacketArgs {
                message_type: kind,
                message: Some(message),
            },
        );
        fb::finish_packet_buffer(b, root);
        b.finished_data()
    }

    fn decode(&mut self, bytes: &[u8]) -> Option<Packet> {
        let p = fb::root_as_packet(bytes).ok()?;
        Some(match p.message_type() {
            fb::Message::Snapshot => {
                let s = p.message_as_snapshot()?;
                Packet::Snapshot(Snapshot {
                    seq: s.seq(),
                    tick: s.tick(),
                    entities: s.entities()?.iter().map(entity).collect(),
                })
            }
            fb::Message::ClientState => {
                let c = p.message_as_client_state()?;
                Packet::ClientState(ClientState {
                    seq: c.seq(),
                    tick: c.tick(),
                    me: entity(c.me()?),
                    buttons: c.buttons(),
                    aim: [c.aim_x(), c.aim_y()],
                })
            }
            fb::Message::Chat => {
                let c = p.message_as_chat()?;
                Packet::Chat(Chat {
                    seq: c.seq(),
                    tick: c.tick(),
                    from: c.from(),
                    channel: c.channel(),
                    text: c.text()?.to_owned(),
                })
            }
            fb::Message::ScriptEvent => {
                let e = p.message_as_script_event()?;
                let mut args = Vec::new();
                for a in e.args()? {
                    args.push(arg(&a)?);
                }
                Packet::ScriptEvent(ScriptEvent {
                    seq: e.seq(),
                    tick: e.tick(),
                    name: e.name()?.to_owned(),
                    args,
                })
            }
            _ => return None,
        })
    }

    fn read(&mut self, bytes: &[u8]) -> Option<u64> {
        let p = fb::root_as_packet(bytes).ok()?;
        Some(match p.message_type() {
            fb::Message::Snapshot => {
                let s = p.message_as_snapshot()?;
                u64::from(s.seq())
                    + u64::from(s.tick())
                    + s.entities()?.iter().map(entity_sum).fold(0, u64::wrapping_add)
            }
            fb::Message::ClientState => {
                let c = p.message_as_client_state()?;
                u64::from(c.seq())
                    + u64::from(c.tick())
                    + entity_sum(c.me()?)
                    + u64::from(c.buttons())
                    + c.aim_x() as u64
                    + c.aim_y() as u64
            }
            fb::Message::Chat => {
                let c = p.message_as_chat()?;
                u64::from(c.seq())
                    + u64::from(c.tick())
                    + u64::from(c.from())
                    + u64::from(c.channel())
                    + c.text()?.len() as u64
            }
            fb::Message::ScriptEvent => {
                let e = p.message_as_script_event()?;
                let mut sum = u64::from(e.seq()) + u64::from(e.tick()) + e.name()?.len() as u64;
                for a in e.args()? {
                    sum = sum.wrapping_add(match a.arg_type() {
                        fb::Arg::BoolArg => u64::from(a.arg_as_bool_arg()?.value()),
                        fb::Arg::IntArg => a.arg_as_int_arg()?.value() as u64,
                        fb::Arg::FloatArg => u64::from(a.arg_as_float_arg()?.value().to_bits()),
                        fb::Arg::StrArg => a.arg_as_str_arg()?.value()?.len() as u64,
                        _ => return None,
                    });
                }
                sum
            }
            _ => return None,
        })
    }

    fn zero_copy(&self) -> bool {
        true
    }
}
